insert into _banque (niveau, question, options, correct, explication) values
  ($wb$debutant$wb$, $wb$Combien de pays partagent la BRVM ?$wb$, $wb$["Trois", "Cinq", "Huit", "Quinze"]$wb$::jsonb, 2, $wb$La BRVM est commune aux huit pays de l’UEMOA : Bénin, Burkina Faso, Côte d’Ivoire, Guinée-Bissau, Mali, Niger, Sénégal et Togo.$wb$),
  ($wb$debutant$wb$, $wb$Qui supervise le marché financier régional ?$wb$, $wb$["La BRVM elle-même", "L’AMF-UMOA", "Chaque SGI pour ses clients", "Le ministère des Finances de chaque pays"]$wb$::jsonb, 1, $wb$L’Autorité des Marchés Financiers de l’UMOA agrée les intermédiaires, contrôle le marché et protège les investisseurs. La BRVM, elle, organise les séances.$wb$),
  ($wb$debutant$wb$, $wb$Pour acheter une action cotée à la BRVM, par qui faut-il passer ?$wb$, $wb$["Directement par la BRVM", "Par une SGI agréée", "Par n’importe quelle banque", "Par la société émettrice"]$wb$::jsonb, 1, $wb$Un particulier ne peut pas passer d’ordre directement : il passe par une Société de Gestion et d’Intermédiation agréée, qui transmet l’ordre et conserve les titres.$wb$),
  ($wb$debutant$wb$, $wb$Le BRVM Composite progresse de 0 % sur une année. Les actionnaires ont-ils forcément gagné 0 % ?$wb$, $wb$["Oui, l’indice mesure tout le gain", "Non : il ignore les dividendes", "Non : l’indice ne compte que les banques", "Oui, sauf pour les détenteurs d’obligations"]$wb$::jsonb, 1, $wb$L’indice est calculé sur les seuls cours. Un actionnaire qui a touché ses dividendes a pu gagner de l’argent même si l’indice n’a pas bougé.$wb$),
  ($wb$debutant$wb$, $wb$Lequel de ces droits une action ne donne-t-elle PAS ?$wb$, $wb$["Voter en assemblée générale", "Percevoir le dividende voté", "Revendre ses titres", "Un revenu garanti chaque année"]$wb$::jsonb, 3, $wb$Le dividende est voté chaque année : il n’est jamais garanti. Une action comporte un risque de perte en capital.$wb$),
  ($wb$debutant$wb$, $wb$1 000 € correspondent à combien de francs CFA ?$wb$, $wb$["655 957 FCFA", "65 596 FCFA", "1 000 000 FCFA", "6 559 570 FCFA"]$wb$::jsonb, 0, $wb$1 000 × 655,957 = 655 957 FCFA, selon la parité fixe entre l’euro et le franc CFA.$wb$),
  ($wb$debutant$wb$, $wb$Pour un investisseur résidant dans la zone euro, la parité euro – franc CFA est :$wb$, $wb$["Flottante, révisée chaque jour", "Fixe", "Indexée sur le dollar", "Révisée chaque mois par la BRVM"]$wb$::jsonb, 1, $wb$La parité est fixe : 1 euro = 655,957 FCFA. Le change ne varie donc pas au jour le jour pour un investisseur de la zone euro ; une modification de parité reste possible, comme en 1994.$wb$),
  ($wb$debutant$wb$, $wb$Qui doit être agréé pour vous permettre d’investir à la BRVM depuis l’étranger ?$wb$, $wb$["Votre banque étrangère", "La SGI, par l’AMF-UMOA", "N’importe quel courtier en ligne international", "Personne, aucun agrément n’est nécessaire"]$wb$::jsonb, 1, $wb$Seule une SGI agréée par l’AMF-UMOA peut transmettre vos ordres à la BRVM, où que vous résidiez.$wb$),
  ($wb$debutant$wb$, $wb$Une plateforme hors UEMOA vous propose des « actions africaines » sans agrément. Que faire ?$wb$, $wb$["Investir un petit montant pour tester d’abord", "Ne rien déposer, vérifier l’agrément", "Y investir si le rendement promis est très élevé", "Demander à un proche d’investir à votre place"]$wb$::jsonb, 1, $wb$Sans agrément, aucun recours : ces plateformes sont une source fréquente d’arnaques visant la diaspora.$wb$),
  ($wb$debutant$wb$, $wb$Les dividendes perçus par un investisseur résidant à l’étranger :$wb$, $wb$["Sont toujours exonérés d’impôt dans tous les pays", "Peuvent aussi être imposés là où vous résidez", "Ne peuvent jamais être virés hors de l’UEMOA", "Sont versés uniquement en euros, sans conversion"]$wb$::jsonb, 1, $wb$Après la retenue à la source du pays de la société, le pays de résidence peut aussi imposer le dividende, selon ses règles et les conventions fiscales.$wb$),
  ($wb$debutant$wb$, $wb$Quel placement offre la liquidité la plus immédiate ?$wb$, $wb$["L’épargne bancaire", "L’immobilier", "Un commerce", "Aucun des trois"]$wb$::jsonb, 0, $wb$L’épargne bancaire est disponible immédiatement, ce qui en fait le support naturel de l’épargne de précaution.$wb$),
  ($wb$debutant$wb$, $wb$Vous achetez une action 10 000 FCFA. Un an plus tard, elle cote 10 600 FCFA et vous avez reçu 400 FCFA de dividende. Quel est votre rendement total ?$wb$, $wb$["4 %", "6 %", "10 %", "16 %"]$wb$::jsonb, 2, $wb$(400 + 10 600 − 10 000) ÷ 10 000 × 100 = 10 % : 4 % de dividende et 6 % de hausse du cours.$wb$),
  ($wb$debutant$wb$, $wb$Pourquoi comparer les placements sur cinq à dix ans ?$wb$, $wb$["Parce que les dividendes ne sont versés qu’au bout de cinq ans", "Parce qu’une seule année peut être exceptionnelle", "Parce que la BRVM ne publie ses cours qu’une fois par an", "Parce que l’immobilier ne se vend qu’après dix ans"]$wb$::jsonb, 1, $wb$Sur une seule année, le hasard pèse lourd. Une longue période donne une image plus fidèle du rendement.$wb$),
  ($wb$debutant$wb$, $wb$Qu’est-ce que le rendement de dividende d’une action ?$wb$, $wb$["Le dividende divisé par le cours, hors variation du cours", "La hausse du cours sur un an", "Le bénéfice de la société divisé par son chiffre d’affaires", "Le rendement total garanti par la société"]$wb$::jsonb, 0, $wb$Rendement de dividende = dividende ÷ cours × 100. Il ne tient pas compte de la variation du cours, qui s’ajoute au rendement total.$wb$),
  ($wb$debutant$wb$, $wb$Par quoi commencer pour bâtir un patrimoine ?$wb$, $wb$["Un portefeuille d’actions diversifié", "Un bien immobilier en location", "Une épargne de précaution", "Un commerce de proximité"]$wb$::jsonb, 2, $wb$L’épargne de précaution couvre les imprévus : elle évite de devoir vendre ses actions ou son bien au mauvais moment.$wb$),
  ($wb$debutant$wb$, $wb$Votre dividende n’est pas arrivé à la date de paiement. Qui contactez-vous en premier ?$wb$, $wb$["La BRVM", "L’AMF-UMOA", "Votre SGI", "La société qui verse le dividende"]$wb$::jsonb, 2, $wb$Votre SGI tient votre compte-titres et votre compte espèces : elle seule peut vérifier ce qui s’est passé sur votre compte. Le régulateur n’intervient qu’en dernier recours.$wb$),
  ($wb$debutant$wb$, $wb$Quel acteur agrée les SGI et contrôle le marché ?$wb$, $wb$["La BRVM", "L’AMF-UMOA", "Le DC/BR", "La BCEAO"]$wb$::jsonb, 1, $wb$L’Autorité des Marchés Financiers de l’UMOA, qui a succédé au CREPMF, agrée les intermédiaires et veille au respect des règles.$wb$),
  ($wb$debutant$wb$, $wb$Quel est le rôle du DC/BR ?$wb$, $wb$["Fixer chaque jour le prix des actions cotées", "Tenir les titres et régler les échanges", "Conseiller les investisseurs particuliers", "Organiser les assemblées générales"]$wb$::jsonb, 1, $wb$Le Dépositaire Central / Banque de Règlement inscrit les titres et règle les espèces entre intermédiaires après chaque échange.$wb$),
  ($wb$debutant$wb$, $wb$Un « conseiller » vous propose sur WhatsApp un placement garanti à 15 % par mois. Que faites-vous ?$wb$, $wb$["Vous versez une petite somme pour tester", "Vous refusez : rien n’est garanti", "Vous demandez une remise sur les frais d’entrée", "Vous attendez que l’offre expire pour décider"]$wb$::jsonb, 1, $wb$Un gain garanti et très élevé est le signe le plus sûr d’une escroquerie. Vérifiez aussi l’agrément sur la liste de l’AMF-UMOA.$wb$),
  ($wb$debutant$wb$, $wb$Où sont inscrites les actions que vous achetez ?$wb$, $wb$["Sur votre compte-titres, chez votre SGI", "Sur un certificat papier envoyé chez vous", "Sur le site de la société", "Sur votre compte bancaire courant"]$wb$::jsonb, 0, $wb$Les titres sont dématérialisés : ils sont inscrits sur votre compte-titres chez votre SGI, et enregistrés au dépositaire central.$wb$),
  ($wb$debutant$wb$, $wb$Une action cote 2 500 FCFA. Vous en achetez 10, avec 1 % de frais. Combien payez-vous ?$wb$, $wb$["2 525 FCFA", "25 000 FCFA", "25 250 FCFA", "27 500 FCFA"]$wb$::jsonb, 2, $wb$10 × 2 500 = 25 000 FCFA, plus 1 % de frais, soit 250 FCFA : 25 250 FCFA au total.$wb$),
  ($wb$debutant$wb$, $wb$Vos frais sont de 1,5 % à l’achat et 1,5 % à la revente. De combien l’action doit-elle monter, environ, pour que l’opération ne perde rien ?$wb$, $wb$["0,75 %", "1,5 %", "3 %", "15 %"]$wb$::jsonb, 2, $wb$Les frais se paient deux fois : 1,5 % + 1,5 % = environ 3 %. En dessous, l’aller-retour est perdant.$wb$),
  ($wb$debutant$wb$, $wb$Une action cote 1 800 FCFA, une autre 30 000 FCFA. Que peut-on en conclure ?$wb$, $wb$["La première est forcément la meilleure affaire", "La seconde est de meilleure qualité", "Rien : le cours dépend surtout du nombre de titres", "La première verse forcément un plus petit dividende"]$wb$::jsonb, 2, $wb$Le cours d’une action ne dit rien de sa qualité ni de sa cherté. Pour juger, il faut rapporter le prix aux bénéfices ou aux dividendes.$wb$),
  ($wb$debutant$wb$, $wb$50 000 FCFA répartis à parts égales sur cinq valeurs. L’une d’elles baisse de 20 %. Combien perd le portefeuille ?$wb$, $wb$["10 000 FCFA", "2 000 FCFA", "4 000 FCFA", "20 000 FCFA"]$wb$::jsonb, 1, $wb$Chaque ligne vaut 10 000 FCFA ; 20 % de 10 000 = 2 000 FCFA, soit 4 % du portefeuille. Sur une seule valeur, la perte aurait été de 10 000 FCFA.$wb$),
  ($wb$debutant$wb$, $wb$Pourquoi éviter de multiplier les très petits ordres ?$wb$, $wb$["La BRVM refuse les ordres de moins de dix titres", "Le minimum de frais par ordre pèse lourd", "Ils ne donnent pas droit au dividende", "Ils sont toujours exécutés en dernier"]$wb$::jsonb, 1, $wb$Beaucoup de SGI appliquent un montant minimum de frais par ordre : sur un petit achat, ce minimum pèse lourd en pourcentage.$wb$),
  ($wb$debutant$wb$, $wb$Vous achetez 200 actions à 5 000 FCFA et les revendez à 5 600 FCFA. Quelle est votre plus-value, hors frais ?$wb$, $wb$["600 FCFA", "12 000 FCFA", "120 000 FCFA", "1 120 000 FCFA"]$wb$::jsonb, 2, $wb$(5 600 − 5 000) × 200 = 600 × 200 = 120 000 FCFA.$wb$),
  ($wb$debutant$wb$, $wb$Vous avez investi 1 000 000 FCFA, reçu 80 000 FCFA de dividendes et réalisé 120 000 FCFA de plus-value. Quel est votre rendement total ?$wb$, $wb$["8 %", "12 %", "20 %", "200 %"]$wb$::jsonb, 2, $wb$(80 000 + 120 000) ÷ 1 000 000 = 200 000 ÷ 1 000 000 = 20 %.$wb$),
  ($wb$debutant$wb$, $wb$Une société lance une augmentation de capital. Quel choix fait perdre de l’argent à coup sûr ?$wb$, $wb$["Exercer tous ses DPS", "Céder ses DPS sur le marché", "Les laisser expirer", "Céder une partie et exercer l’autre"]$wb$::jsonb, 2, $wb$Les droits non utilisés perdent leur valeur à la fin de la période de souscription. Les exercer ou les céder préserve leur valeur.$wb$),
  ($wb$debutant$wb$, $wb$Vous achetez une action la veille du détachement, juste pour toucher le dividende. Que se passe-t-il ?$wb$, $wb$["Vous gagnez le dividende sans aucune contrepartie", "Le cours baisse d’environ le dividende", "Le dividende vous est refusé par la société", "La société vous rembourse les frais d’achat"]$wb$::jsonb, 1, $wb$Au détachement, le cours est ajusté du dividende. Le gain apparent est compensé, et les frais d’achat restent à votre charge.$wb$),
  ($wb$debutant$wb$, $wb$Une société a versé un dividende chaque année depuis dix ans. Que pouvez-vous en déduire ?$wb$, $wb$["Le dividende est garanti pour l’an prochain", "Il peut baisser ou disparaître", "Il augmentera forcément l’an prochain", "La société ne peut plus le supprimer"]$wb$::jsonb, 1, $wb$La régularité passée est un bon signe, pas une garantie : l’assemblée générale décide chaque année.$wb$),
  ($wb$debutant$wb$, $wb$Vous détenez 200 actions et la société verse 1 500 FCFA par action. Quel est votre revenu brut ?$wb$, $wb$["30 000 FCFA", "150 000 FCFA", "300 000 FCFA", "3 000 000 FCFA"]$wb$::jsonb, 2, $wb$Revenu brut = nombre d’actions × dividende par action : 200 × 1 500 = 300 000 FCFA.$wb$),
  ($wb$debutant$wb$, $wb$Une action cote 20 000 FCFA et verse un dividende annuel de 1 200 FCFA. Quel est son rendement ?$wb$, $wb$["1,2 %", "6 %", "12 %", "16,7 %"]$wb$::jsonb, 1, $wb$Rendement = dividende ÷ cours × 100 : 1 200 ÷ 20 000 × 100 = 6 %.$wb$),
  ($wb$debutant$wb$, $wb$Quelle stratégie amplifie vos dividendes par effet boule de neige ?$wb$, $wb$["Vendre ses actions dès réception du dividende", "Placer les dividendes sur un compte bancaire", "Réinvestir les dividendes en actions", "Attendre 5 ans avant de toucher à son portefeuille"]$wb$::jsonb, 2, $wb$Les actions achetées avec le dividende rapportent à leur tour un dividende l’année suivante, qui permet d’en acheter davantage.$wb$),
  ($wb$debutant$wb$, $wb$Pour percevoir le prochain dividende, jusqu’à quand faut-il détenir l’action ?$wb$, $wb$["Le jour du paiement", "La veille de la date de détachement", "Le jour de l’assemblée générale", "Un an avant le paiement"]$wb$::jsonb, 1, $wb$Il faut détenir l’action la veille du détachement. Acheter le jour du détachement ou après ne donne pas droit au dividende en cours.$wb$),
  ($wb$debutant$wb$, $wb$Une action affiche un rendement de 15 %, bien au-dessus des autres. Que peut-on en conclure ?$wb$, $wb$["C’est forcément un excellent placement", "Le dividende va augmenter l’an prochain", "Il faut vérifier d’où vient ce chiffre", "La société est sûrement la plus rentable du marché"]$wb$::jsonb, 2, $wb$Un rendement très élevé est un signal à vérifier, pas une garantie : il peut venir d’un cours qui a chuté, ou d’un dividende que le marché juge intenable.$wb$),
  ($wb$debutant$wb$, $wb$Quel capital faut-il pour viser 600 000 FCFA de dividendes bruts par an, à 8 % de rendement hypothétique ?$wb$, $wb$["48 000 FCFA", "4 800 000 FCFA", "7 500 000 FCFA", "10 000 000 FCFA"]$wb$::jsonb, 2, $wb$Capital = revenu visé ÷ rendement : 600 000 ÷ 8 % = 7 500 000 FCFA. À 6 %, il en faudrait 10 000 000.$wb$),
  ($wb$debutant$wb$, $wb$Pourquoi ne faut-il pas investir son épargne d’urgence en bourse ?$wb$, $wb$["Parce que les dividendes y sont imposés à la source", "Parce que la bourse est réservée aux résidents ivoiriens", "Parce qu’il faudrait peut-être vendre en pleine baisse", "Parce que les SGI refusent les petits montants"]$wb$::jsonb, 2, $wb$Les actions peuvent perdre de la valeur à court terme. Si un imprévu survient, vous pourriez devoir vendre à perte. L’épargne de précaution doit rester disponible, à l’écart des variations de la bourse.$wb$),
  ($wb$debutant$wb$, $wb$Votre revenu de dividendes vient à parts égales de cinq sociétés. L’une divise son dividende par deux. De combien baisse votre revenu total ?$wb$, $wb$["−50 %", "−20 %", "−10 %", "−5 %"]$wb$::jsonb, 2, $wb$Chaque société pèse 20 % du revenu. La moitié de 20 %, c’est 10 % du revenu total.$wb$),
  ($wb$debutant$wb$, $wb$Quel risque la diversification réduit-elle le plus directement ?$wb$, $wb$["Le risque de marché", "Le risque propre à une entreprise", "Le risque de change", "Tous les risques à la fois"]$wb$::jsonb, 1, $wb$Répartir entre plusieurs sociétés limite l’effet d’une mauvaise nouvelle sur l’une d’elles. Une baisse générale du marché, elle, touche toutes les lignes.$wb$),
  ($wb$debutant$wb$, $wb$Qu’appelle-t-on le risque de liquidité ?$wb$, $wb$["La perte de valeur due à l’inflation chaque année", "La difficulté à vendre sans faire baisser le prix", "La faillite d’une société cotée", "La variation du franc CFA face au dollar"]$wb$::jsonb, 1, $wb$Sur une valeur peu échangée, il peut y avoir peu d’acheteurs : il faut alors attendre, ou accepter un prix plus bas.$wb$),
  ($wb$debutant$wb$, $wb$Vos dépenses mensuelles essentielles sont de 200 000 FCFA. Combien prévoir pour six mois d’épargne de précaution ?$wb$, $wb$["600 000 FCFA", "1 200 000 FCFA", "2 000 000 FCFA", "200 000 FCFA"]$wb$::jsonb, 1, $wb$200 000 × 6 = 1 200 000 FCFA, à garder disponibles et séparés du portefeuille boursier.$wb$),
  ($wb$debutant$wb$, $wb$Vous passez un ordre d’achat à cours limité à 3 270 FCFA ; le vendeur le moins cher demande 3 280 FCFA. Que se passe-t-il ?$wb$, $wb$["L’ordre est exécuté tout de suite à 3 280 FCFA", "L’ordre attend un vendeur à 3 270 FCFA ou moins", "L’ordre est exécuté à 3 270 FCFA, quoi qu’il arrive ensuite", "La BRVM rejette l’ordre"]$wb$::jsonb, 1, $wb$Un ordre à cours limité ne s’exécute jamais au-delà de sa limite. Il reste en attente pendant sa durée de validité.$wb$),
  ($wb$debutant$wb$, $wb$Que signifie un ordre « tout ou rien » ?$wb$, $wb$["Il est exécuté au meilleur prix disponible", "Il ne peut pas être servi partiellement", "Il reste valable trois mois", "Il n’a pas de limite de prix"]$wb$::jsonb, 1, $wb$Le règlement général de la BRVM définit l’ordre « tout ou rien » comme un ordre qui ne peut pas être répondu partiellement.$wb$),
  ($wb$debutant$wb$, $wb$Vous ne précisez pas la durée de validité de votre ordre. Comment est-il considéré ?$wb$, $wb$["Mensuel, jusqu’à la fin du mois en cours", "Jour : valable une seule séance", "À exécution, valable pendant trois mois", "Annulé avant même d’être transmis"]$wb$::jsonb, 1, $wb$Selon le règlement général de la BRVM, un ordre sans indication de validité est réputé « jour ».$wb$),
  ($wb$debutant$wb$, $wb$Vous détenez 200 actions versant 1 200 FCFA et 100 actions versant 400 FCFA. Quel est votre revenu annuel de dividendes ?$wb$, $wb$["160 000 FCFA", "280 000 FCFA", "320 000 FCFA", "1 600 FCFA"]$wb$::jsonb, 1, $wb$(200 × 1 200) + (100 × 400) = 240 000 + 40 000 = 280 000 FCFA.$wb$),
  ($wb$debutant$wb$, $wb$Quel capital faut-il pour recevoir 1 000 000 FCFA par an, à 8 % de rendement hypothétique ?$wb$, $wb$["8 000 000 FCFA", "12 500 000 FCFA", "80 000 FCFA", "125 000 000 FCFA"]$wb$::jsonb, 1, $wb$Capital = revenu visé ÷ rendement : 1 000 000 ÷ 8 % = 12 500 000 FCFA.$wb$),
  ($wb$debutant$wb$, $wb$Pourquoi réduire la part en actions quelques années avant les études ?$wb$, $wb$["Parce que les dividendes cessent avant l’échéance", "Pour ne pas vendre en baisse au mauvais moment", "Parce que les SGI ferment les comptes des parents", "Pour payer moins de frais de courtage"]$wb$::jsonb, 1, $wb$Près de l’échéance, on ne peut plus attendre qu’un cours remonte : sécuriser progressivement évite de vendre au plus bas.$wb$),
  ($wb$debutant$wb$, $wb$1 000 FCFA placés à 10 % par an pendant 10 ans deviennent environ :$wb$, $wb$["2 000 FCFA", "2 594 FCFA", "1 100 FCFA", "10 000 FCFA"]$wb$::jsonb, 1, $wb$1 000 × 1,10 ^ 10 ≈ 2 594 FCFA : les gains de chaque année produisent à leur tour des gains.$wb$),
  ($wb$debutant$wb$, $wb$Dans ce projet, à quoi sert le réinvestissement des dividendes ?$wb$, $wb$["À payer les frais de scolarité chaque année", "À accroître les dividendes futurs", "À éviter tout risque de baisse du capital", "À garantir le rendement du projet"]$wb$::jsonb, 1, $wb$Chaque dividende réinvesti achète de nouvelles actions, qui rapportent à leur tour : le revenu grandit d’année en année.$wb$),
  ($wb$debutant$wb$, $wb$Quelle stratégie vise d’abord un revenu régulier ?$wb$, $wb$["La stratégie valeur", "La stratégie revenu", "La stratégie croissance", "Le trading quotidien"]$wb$::jsonb, 1, $wb$La stratégie revenu vise des dividendes réguliers, encaissés ou réinvestis. Elle demande peu de suivi quotidien.$wb$),
  ($wb$debutant$wb$, $wb$Une action cote 12 000 FCFA et son bénéfice par action est de 1 500 FCFA. Quel est son PER ?$wb$, $wb$["5", "8", "18", "0,125"]$wb$::jsonb, 1, $wb$PER = cours ÷ bénéfice par action = 12 000 ÷ 1 500 = 8.$wb$),
  ($wb$debutant$wb$, $wb$Un PER très bas signifie-t-il toujours une bonne affaire ?$wb$, $wb$["Oui, dans tous les cas", "Non : les bénéfices peuvent reculer", "Oui, dès qu’il est inférieur à 20", "Non, un PER bas est toujours mauvais signe"]$wb$::jsonb, 1, $wb$Un PER bas peut signaler une décote… ou une société en difficulté. Il se compare au secteur et à l’historique de la société.$wb$),
  ($wb$debutant$wb$, $wb$Sur quel horizon juger une action achetée pour son dividende ?$wb$, $wb$["Une semaine", "Trois mois", "Cinq ans environ", "Un jour"]$wb$::jsonb, 2, $wb$Une stratégie de revenu se juge sur la régularité des dividendes, donc sur plusieurs années.$wb$),
  ($wb$debutant$wb$, $wb$Quelle stratégie accepte de recevoir peu de dividendes en échange d’un potentiel de plus-value ?$wb$, $wb$["La stratégie valeur", "La stratégie revenu", "La stratégie croissance", "Aucune"]$wb$::jsonb, 2, $wb$La stratégie croissance mise sur la progression de l’activité et du cours, au prix d’une volatilité plus forte.$wb$),
  ($wb$debutant$wb$, $wb$Quel type d’ordre permet de contrôler son prix d’achat ?$wb$, $wb$["Ordre au mieux, pour être servi au plus vite", "Ordre à cours limité, avec un prix maximum", "Ordre stop, déclenché à un seuil de prix", "Aucun : tous les ordres se valent"]$wb$::jsonb, 1, $wb$L’ordre à cours limité fixe un prix maximum d’achat : vous maîtrisez votre coût d’entrée, en particulier sur les valeurs peu liquides.$wb$),
  ($wb$debutant$wb$, $wb$Par qui faut-il passer pour acheter des actions à la BRVM ?$wb$, $wb$["Sa banque, directement au guichet", "Une SGI agréée", "N’importe quelle plateforme en ligne", "La BCEAO"]$wb$::jsonb, 1, $wb$Seules les Sociétés de Gestion et d’Intermédiation agréées peuvent transmettre des ordres au marché de la BRVM.$wb$),
  ($wb$debutant$wb$, $wb$Quelle autorité agrée les SGI de l’UMOA ?$wb$, $wb$["La BCEAO", "L’AMF-UMOA (ex-CREPMF)", "La BRVM elle-même", "Le ministère des Finances de chaque pays"]$wb$::jsonb, 1, $wb$L’Autorité des Marchés Financiers de l’UMOA, qui a succédé au CREPMF, agrée et contrôle les SGI.$wb$),
  ($wb$debutant$wb$, $wb$Vous achetez 20 actions à 10 000 FCFA avec 1 % de frais. Quel est le coût total ?$wb$, $wb$["200 000 FCFA", "202 000 FCFA", "220 000 FCFA", "200 100 FCFA"]$wb$::jsonb, 1, $wb$20 × 10 000 = 200 000 FCFA, plus 1 % de frais (2 000 FCFA) : 202 000 FCFA.$wb$),
  ($wb$debutant$wb$, $wb$Un ordre d’achat à cours limité à 10 000 FCFA s’exécute :$wb$, $wb$["À 10 000 FCFA ou moins", "Seulement au-dessus de 10 000 FCFA", "Toujours immédiatement, quel que soit le prix", "Au cours d’ouverture, quel qu’il soit"]$wb$::jsonb, 0, $wb$Pour un achat, la limite est un prix maximum : l’ordre s’exécute à 10 000 FCFA ou en dessous ; sinon il reste en attente pendant sa durée de validité.$wb$),
  ($wb$intermediaire$wb$, $wb$Quel document indique si les comptes sont certifiés ?$wb$, $wb$["Le compte de résultat", "Le rapport des commissaires aux comptes", "Le rapport d’activité trimestriel", "L’avis de convocation à l’assemblée générale"]$wb$::jsonb, 1, $wb$Les commissaires aux comptes certifient les comptes, avec ou sans réserve. C’est la première chose à lire.$wb$),
  ($wb$intermediaire$wb$, $wb$Une société affiche un résultat net en forte hausse, mais son flux de trésorerie opérationnel est négatif. Que vérifier en priorité ?$wb$, $wb$["Rien, le résultat suffit", "L’évolution des créances clients et des stocks", "Le nombre d’administrateurs", "Le cours de l’action"]$wb$::jsonb, 1, $wb$Un bénéfice qui ne devient pas trésorerie vient souvent de créances ou de stocks qui augmentent. Ce n’est pas forcément grave, mais il faut comprendre pourquoi.$wb$),
  ($wb$intermediaire$wb$, $wb$Que montre le bilan ?$wb$, $wb$["Les ventes et les charges de toute l’année", "Le patrimoine et son financement, à une date", "L’argent entré et sorti de la société dans l’année", "Le cours moyen de l’action sur l’exercice"]$wb$::jsonb, 1, $wb$Le bilan est une photographie à la date de clôture : actif d’un côté, fonds propres et dettes de l’autre.$wb$),
  ($wb$intermediaire$wb$, $wb$Pourquoi regarder le résultat d’exploitation, pas seulement le résultat net ?$wb$, $wb$["Il est toujours plus élevé que le résultat net", "Il montre l’activité courante", "Il inclut le dividende versé aux actionnaires", "Il est le seul chiffre certifié des comptes"]$wb$::jsonb, 1, $wb$Le résultat d’exploitation reflète l’activité courante. Une cession exceptionnelle peut gonfler le résultat net d’une seule année.$wb$),
  ($wb$intermediaire$wb$, $wb$Des états financiers publiés « provisoires, non approuvés par l’assemblée générale » :$wb$, $wb$["Ne peuvent plus changer une fois publiés", "Peuvent encore être modifiés", "Sont faux tant qu’ils ne sont pas approuvés", "Ne sont communiqués qu’aux administrateurs"]$wb$::jsonb, 1, $wb$Des comptes provisoires peuvent évoluer jusqu’à l’assemblée générale. Ils sont utiles, à condition de le savoir.$wb$),
  ($wb$intermediaire$wb$, $wb$Une action cote 4 500 FCFA ; son bénéfice par action est de 300 FCFA. Quel est son PER ?$wb$, $wb$["10", "15", "20", "1 350"]$wb$::jsonb, 1, $wb$4 500 ÷ 300 = 15.$wb$),
  ($wb$intermediaire$wb$, $wb$Une société a gagné 5 milliards et compte 20 millions d’actions. Quel est son BPA ?$wb$, $wb$["25 FCFA", "250 FCFA", "2 500 FCFA", "4 FCFA"]$wb$::jsonb, 1, $wb$5 000 000 000 ÷ 20 000 000 = 250 FCFA par action.$wb$),
  ($wb$intermediaire$wb$, $wb$Une société a un PER de 4, nettement sous ses concurrents. Quelle est la bonne réaction ?$wb$, $wb$["Acheter immédiatement, avant la hausse", "Chercher d’abord pourquoi", "Vendre immédiatement si vous en détenez", "Ignorer le PER, qui n’a aucun sens"]$wb$::jsonb, 1, $wb$Un PER très bas peut être une opportunité, ou le signe d’un problème. Il faut l’expliquer avant de conclure.$wb$),
  ($wb$intermediaire$wb$, $wb$Avec quelle société comparer le PER d’un opérateur télécom ?$wb$, $wb$["Une banque", "Un autre opérateur télécom", "Une société agricole", "L’indice BRVM Composite seul"]$wb$::jsonb, 1, $wb$Les PER « normaux » varient d’un secteur à l’autre. La comparaison utile se fait dans le même secteur.$wb$),
  ($wb$intermediaire$wb$, $wb$Une société affiche une perte. Que vaut son PER ?$wb$, $wb$["Il est très attractif", "Il n’a pas de sens", "Il vaut zéro", "Il vaut 100"]$wb$::jsonb, 1, $wb$Avec un bénéfice négatif, le PER n’a pas de signification économique.$wb$),
  ($wb$intermediaire$wb$, $wb$Une société a 50 milliards de fonds propres et a gagné 10 milliards. Quel est son ROE ?$wb$, $wb$["5 %", "20 %", "50 %", "500 %"]$wb$::jsonb, 1, $wb$10 ÷ 50 = 20 %.$wb$),
  ($wb$intermediaire$wb$, $wb$Une société a un PER de 8 et un ROE de 25 %. Quel est son P/B ?$wb$, $wb$["0,32", "2", "3,1", "33"]$wb$::jsonb, 1, $wb$P/B = PER × ROE = 8 × 0,25 = 2.$wb$),
  ($wb$intermediaire$wb$, $wb$Une action cote 2 000 FCFA et verse 140 FCFA de dividende. Quel est son rendement ?$wb$, $wb$["1,4 %", "7 %", "14 %", "70 %"]$wb$::jsonb, 1, $wb$140 ÷ 2 000 = 7 %.$wb$),
  ($wb$intermediaire$wb$, $wb$Pourquoi un ROE très élevé n’est-il pas toujours une bonne nouvelle ?$wb$, $wb$["Il signifie que la société est surévaluée", "Il peut venir de fonds propres trop faibles", "Il réduit forcément le dividende versé", "Il n’est pas publié par les sociétés de la BRVM"]$wb$::jsonb, 1, $wb$Un ROE élevé avec peu de fonds propres peut cacher un endettement important. Il faut regarder la structure du bilan.$wb$),
  ($wb$intermediaire$wb$, $wb$Une action cote sous sa valeur comptable (P/B inférieur à 1). Que faut-il en conclure ?$wb$, $wb$["C’est forcément une bonne affaire à saisir", "Il faut chercher pourquoi", "La société va bientôt faire faillite", "Le ratio est faux, la valeur comptable aussi"]$wb$::jsonb, 1, $wb$Une décote peut être une opportunité ou refléter une rentabilité faible. Le ROE aide à trancher.$wb$),
  ($wb$intermediaire$wb$, $wb$Comment s’appelle le « chiffre d’affaires » d’une banque ?$wb$, $wb$["Le résultat d’exploitation", "Le produit net bancaire", "Le coût du risque", "La capitalisation"]$wb$::jsonb, 1, $wb$Le produit net bancaire regroupe la marge d’intérêts et les commissions.$wb$),
  ($wb$intermediaire$wb$, $wb$Une banque a 120 Md de produit net bancaire et 48 Md de frais généraux. Quel est son coefficient d’exploitation ?$wb$, $wb$["25 %", "40 %", "60 %", "250 %"]$wb$::jsonb, 1, $wb$48 ÷ 120 = 40 %.$wb$),
  ($wb$intermediaire$wb$, $wb$Que mesure le coût du risque ?$wb$, $wb$["Le prix de l’action sur la dernière année", "Les pertes probables sur les prêts", "Les salaires et frais généraux", "Le dividende versé par action"]$wb$::jsonb, 1, $wb$Le coût du risque enregistre les prêts qui ne seront probablement pas remboursés.$wb$),
  ($wb$intermediaire$wb$, $wb$Pourquoi un ratio d’endettement classique n’a-t-il pas de sens pour une banque ?$wb$, $wb$["Les banques n’ont pas de dettes au bilan", "Les dépôts sont des dettes : c’est son métier", "Il est interdit de le publier pour une banque cotée", "Il vaut toujours zéro pour une banque"]$wb$::jsonb, 1, $wb$Le métier de la banque consiste à collecter des ressources pour prêter. On mesure sa solidité par la solvabilité.$wb$),
  ($wb$intermediaire$wb$, $wb$Pour comparer des banques cotées, quel ratio de valorisation est souvent le plus parlant ?$wb$, $wb$["Le P/B, lu avec le ROE", "Le nombre d’agences", "Le volume d’échanges", "La date de création"]$wb$::jsonb, 0, $wb$Les actifs d’une banque sont des prêts inscrits à leur valeur au bilan : le P/B, lu avec le ROE, est très utilisé.$wb$),
  ($wb$intermediaire$wb$, $wb$Quel risque la diversification ne peut-elle pas supprimer ?$wb$, $wb$["Le risque propre à une société", "Le risque de marché", "Le risque d’un mauvais résultat", "Le risque d’un litige"]$wb$::jsonb, 1, $wb$Une crise générale touche toutes les actions : multiplier les lignes ne protège pas contre le risque de marché.$wb$),
  ($wb$intermediaire$wb$, $wb$Un portefeuille compte dix lignes, toutes des banques. Est-il bien diversifié ?$wb$, $wb$["Oui, dix lignes suffisent", "Non, il reste exposé à un seul secteur", "Oui, à condition que ce soit dix pays différents", "La question n’a pas de sens"]$wb$::jsonb, 1, $wb$Dix banques réagissent souvent ensemble aux mêmes nouvelles. La répartition par secteur compte autant que le nombre de lignes.$wb$),
  ($wb$intermediaire$wb$, $wb$Pourquoi des lignes trop petites posent-elles problème ?$wb$, $wb$["Elles sont interdites par le règlement de la BRVM", "Les frais minimum pèsent lourd", "Elles ne versent pas de dividende", "Elles augmentent le risque de marché"]$wb$::jsonb, 1, $wb$Les frais de courtage comportent souvent un minimum : sur un petit ordre, ils représentent un pourcentage élevé.$wb$),
  ($wb$intermediaire$wb$, $wb$Une ligne a beaucoup monté et pèse désormais 40 % du portefeuille. Que suggère le principe de diversification ?$wb$, $wb$["Ne rien faire", "Envisager de rééquilibrer pour réduire sa part", "Acheter encore la même valeur", "Vendre toutes les autres lignes"]$wb$::jsonb, 1, $wb$Rééquilibrer ramène le portefeuille vers sa répartition cible et limite la dépendance à une seule société.$wb$),
  ($wb$intermediaire$wb$, $wb$Pourquoi suivre l’indice BRVM Composite n’équivaut-il pas forcément à être diversifié ?$wb$, $wb$["Il ne contient qu’une seule société cotée", "Il est pondéré par la capitalisation", "Il ne contient que des obligations d’État", "Il n’est plus publié par la BRVM"]$wb$::jsonb, 1, $wb$Un indice pondéré par la capitalisation peut être dominé par quelques grandes sociétés.$wb$),
  ($wb$intermediaire$wb$, $wb$Une action cote 8 000 FCFA. La société émet 1 action nouvelle pour 3 anciennes à 6 000 FCFA. Quelle est la valeur théorique du DPS ?$wb$, $wb$["250 FCFA", "500 FCFA", "667 FCFA", "2 000 FCFA"]$wb$::jsonb, 1, $wb$(8 000 − 6 000) ÷ (3 + 1) = 500 FCFA.$wb$),
  ($wb$intermediaire$wb$, $wb$Dans le même exemple, quel est le cours théorique après détachement ?$wb$, $wb$["6 000 FCFA", "7 500 FCFA", "8 000 FCFA", "8 500 FCFA"]$wb$::jsonb, 1, $wb$8 000 − 500 = 7 500 FCFA. Vérification : (3 × 8 000 + 6 000) ÷ 4 = 7 500.$wb$),
  ($wb$intermediaire$wb$, $wb$Que se passe-t-il si vous ne faites rien de vos droits ?$wb$, $wb$["Ils sont automatiquement exercés", "Ils expirent sans valeur à la clôture", "Ils se transforment en dividende", "Ils sont remboursés au nominal"]$wb$::jsonb, 1, $wb$Un droit non exercé et non vendu à la clôture perd toute valeur.$wb$),
  ($wb$intermediaire$wb$, $wb$Le jour du détachement, le cours baisse d’un montant proche de la valeur du droit. Est-ce une perte pour l’actionnaire ?$wb$, $wb$["Oui, une perte définitive pour l’actionnaire", "Non : la valeur du droit la compense", "Oui, sauf si le dividende est maintenu", "Non, le cours ne bouge jamais ce jour-là"]$wb$::jsonb, 1, $wb$La valeur se répartit entre l’action ex-droit et le droit. L’actionnaire ne s’appauvrit que s’il laisse le droit expirer.$wb$),
  ($wb$intermediaire$wb$, $wb$Pourquoi lire l’objet d’une augmentation de capital avant de souscrire ?$wb$, $wb$["Ce n’est pas utile, seul le prix compte", "Son usage change le risque pris", "Pour connaître le nom de la SGI chef de file", "Pour savoir si la société verse un dividende"]$wb$::jsonb, 1, $wb$L’usage des fonds levés dit beaucoup sur la situation de la société.$wb$),
  ($wb$intermediaire$wb$, $wb$Pour viser 400 000 FCFA de dividendes par an avec un rendement de 8 %, quelle somme faut-il investir ?$wb$, $wb$["3 200 000 FCFA", "5 000 000 FCFA", "8 000 000 FCFA", "32 000 000 FCFA"]$wb$::jsonb, 1, $wb$400 000 ÷ 0,08 = 5 000 000 FCFA.$wb$),
  ($wb$intermediaire$wb$, $wb$Vous détenez 100 actions à 10 000 FCFA ; le dividende est de 600 FCFA, entièrement réinvesti au même cours. Combien d’actions achetez-vous ?$wb$, $wb$["3", "6", "10", "60"]$wb$::jsonb, 1, $wb$100 × 600 = 60 000 FCFA, soit 6 actions à 10 000 FCFA.$wb$),
  ($wb$intermediaire$wb$, $wb$Qu’est-ce qu’une simulation ne peut pas faire ?$wb$, $wb$["Comparer deux scénarios", "Garantir le résultat futur", "Montrer l’effet du réinvestissement", "Donner un ordre de grandeur"]$wb$::jsonb, 1, $wb$Une simulation applique des hypothèses ; elle ne garantit rien.$wb$),
  ($wb$intermediaire$wb$, $wb$Pourquoi viser un rendement très élevé augmente-t-il le risque ?$wb$, $wb$["Ce n’est pas le cas sur un horizon long", "Il va souvent avec un dividende fragile", "Les frais de courtage sont alors plus élevés", "L’impôt sur les dividendes est plus élevé"]$wb$::jsonb, 1, $wb$Un rendement élevé peut annoncer un dividende réduit. Il faut vérifier sa régularité.$wb$),
  ($wb$intermediaire$wb$, $wb$À quoi sert le portefeuille virtuel ?$wb$, $wb$["À investir de l’argent réel, sans payer de frais", "À tester une stratégie sans argent réel", "À obtenir des dividendes gratuits", "À réduire l’impôt sur ses dividendes"]$wb$::jsonb, 1, $wb$Il reproduit les achats et ventes aux cours réels, sans argent engagé.$wb$),
  ($wb$intermediaire$wb$, $wb$Une société ivoirienne verse un dividende brut de 1 500 FCFA. Avec un IRVM de 12 %, quel est le dividende net ?$wb$, $wb$["1 200 FCFA", "1 320 FCFA", "1 380 FCFA", "1 500 FCFA"]$wb$::jsonb, 1, $wb$1 500 × (1 − 0,12) = 1 320 FCFA.$wb$),
  ($wb$intermediaire$wb$, $wb$Qui retient l’IRVM sur un dividende ?$wb$, $wb$["L’actionnaire, dans sa déclaration annuelle", "La société, au moment du versement", "La BRVM, à la fin de l’année", "Personne"]$wb$::jsonb, 1, $wb$L’IRVM est une retenue à la source : la société le prélève avant de verser le dividende net.$wb$),
  ($wb$intermediaire$wb$, $wb$Quel pays détermine le taux d’IRVM d’un dividende ?$wb$, $wb$["Le pays de l’investisseur", "Le pays de la société qui verse le dividende", "Le pays de la SGI", "Le pays de la banque de l’investisseur"]$wb$::jsonb, 1, $wb$La retenue suit la législation du pays de la société émettrice.$wb$),
  ($wb$intermediaire$wb$, $wb$Un montant publié est déjà net d’impôt. Que se passe-t-il si vous lui retirez encore l’IRVM ?$wb$, $wb$["Rien", "Vous sous-estimez votre revenu et votre rendement", "Vous surestimez votre revenu", "Vous payez deux fois l’impôt"]$wb$::jsonb, 1, $wb$Retirer l’impôt d’un montant déjà net donne un revenu calculé trop bas.$wb$),
  ($wb$intermediaire$wb$, $wb$Les coupons des obligations d’État de l’UEMOA sont :$wb$, $wb$["Imposés au même taux que les dividendes", "En principe exonérés", "Imposés à 50 %", "Interdits aux particuliers"]$wb$::jsonb, 1, $wb$Les titres publics des États et des institutions régionales sont en principe exonérés.$wb$),
  ($wb$intermediaire$wb$, $wb$Une obligation de nominal 10 000 FCFA verse un coupon de 7 %. Combien rapporte-t-elle par an, avant impôt ?$wb$, $wb$["70 FCFA", "700 FCFA", "7 000 FCFA", "10 700 FCFA"]$wb$::jsonb, 1, $wb$10 000 × 7 % = 700 FCFA.$wb$),
  ($wb$intermediaire$wb$, $wb$Vous achetez cette obligation 10 500 FCFA. Son rendement courant est-il supérieur ou inférieur à 7 % ?$wb$, $wb$["Supérieur", "Inférieur", "Égal", "Impossible à dire"]$wb$::jsonb, 1, $wb$700 ÷ 10 500 ≈ 6,7 % : payer au-dessus du pair réduit le rendement.$wb$),
  ($wb$intermediaire$wb$, $wb$Que se passe-t-il pour le prix d’une obligation existante quand les taux du marché montent ?$wb$, $wb$["Il monte", "Il baisse", "Il ne bouge pas", "Le coupon augmente"]$wb$::jsonb, 1, $wb$Les nouvelles émissions rapportent plus : le prix des anciennes baisse pour s’aligner.$wb$),
  ($wb$intermediaire$wb$, $wb$Dans un emprunt à amortissement constant, le coupon versé chaque année :$wb$, $wb$["Augmente", "Diminue, car le capital restant diminue", "Reste identique", "Est nul"]$wb$::jsonb, 1, $wb$Le coupon se calcule sur le capital restant dû, qui baisse à chaque remboursement.$wb$),
  ($wb$intermediaire$wb$, $wb$Une obligation affiche le même cours depuis des mois. Qu’en conclure ?$wb$, $wb$["Que le titre est très stable et sans risque", "Qu’il s’échange peut-être très peu", "Qu’il va bientôt monter vers le pair", "Qu’il est garanti par l’État émetteur"]$wb$::jsonb, 1, $wb$Sans échange, le cours affiché ne bouge pas. Ce n’est pas un prix auquel on est sûr de vendre.$wb$),
  ($wb$intermediaire$wb$, $wb$Un fonds a un actif net de 2 milliards de FCFA et 400 000 parts. Quelle est sa valeur liquidative ?$wb$, $wb$["500 FCFA", "5 000 FCFA", "50 000 FCFA", "800 FCFA"]$wb$::jsonb, 1, $wb$2 000 000 000 ÷ 400 000 = 5 000 FCFA par part.$wb$),
  ($wb$intermediaire$wb$, $wb$Vous investissez 2 000 000 FCFA avec 3 % de frais d’entrée. Combien est réellement investi ?$wb$, $wb$["1 400 000 FCFA", "1 940 000 FCFA", "2 000 000 FCFA", "2 060 000 FCFA"]$wb$::jsonb, 1, $wb$2 000 000 × 3 % = 60 000 FCFA de frais ; 1 940 000 FCFA sont investis.$wb$),
  ($wb$intermediaire$wb$, $wb$Qui conserve les actifs d’un OPCVM ?$wb$, $wb$["Le gérant, sur son propre compte", "Un dépositaire", "La BRVM", "Chaque épargnant"]$wb$::jsonb, 1, $wb$Le dépositaire conserve les actifs, séparés de ceux de la société de gestion.$wb$),
  ($wb$intermediaire$wb$, $wb$Quelle autorité agrée les OPCVM dans l’UEMOA ?$wb$, $wb$["La BCEAO", "L’AMF-UMOA", "La BRVM", "Chaque SGI"]$wb$::jsonb, 1, $wb$L’AMF-UMOA, qui a succédé au CREPMF, agrée et contrôle les OPCVM et leurs sociétés de gestion.$wb$),
  ($wb$intermediaire$wb$, $wb$Un fonds investi en actions promet un rendement « garanti » de 15 % par an. Quelle est la bonne réaction ?$wb$, $wb$["Souscrire vite, avant la clôture de l’offre", "Se méfier : rien ne garantit ce rendement", "Négocier les frais d’entrée et de sortie", "Demander une garantie écrite à 20 %"]$wb$::jsonb, 1, $wb$La valeur d’un fonds actions suit le marché : aucun rendement élevé ne peut y être garanti.$wb$),
  ($wb$avance$wb$, $wb$Les sommets et les creux d’un cours sont de plus en plus hauts. Quelle est la tendance ?$wb$, $wb$["Baissière", "Haussière", "Sans tendance", "Impossible à dire"]$wb$::jsonb, 1, $wb$Des sommets et des creux de plus en plus hauts définissent une tendance haussière.$wb$),
  ($wb$avance$wb$, $wb$Qu’est-ce qu’un support ?$wb$, $wb$["Le cours le plus haut de l’année écoulée", "Un niveau où la baisse a cessé plusieurs fois", "Le cours moyen pondéré des vingt dernières séances", "Le volume moyen"]$wb$::jsonb, 1, $wb$Un support est une zone de prix où des acheteurs sont apparus à plusieurs reprises.$wb$),
  ($wb$avance$wb$, $wb$Un cours monte de 5 % avec un volume très faible. Comment lire ce mouvement ?$wb$, $wb$["Comme très solide", "Comme fragile : peu d’échanges l’ont produit", "Comme une garantie de hausse", "Comme une erreur"]$wb$::jsonb, 1, $wb$Sans volume, un mouvement peut venir de quelques ordres isolés.$wb$),
  ($wb$avance$wb$, $wb$Une valeur n’a pas été échangée depuis dix séances. Que vaut son cours affiché ?$wb$, $wb$["Le prix exact du marché aujourd’hui", "Le dernier prix échangé, sans plus", "Zéro, faute d’échange", "La moyenne des cours de son secteur"]$wb$::jsonb, 1, $wb$Sans échange, le cours reste figé : ce n’est pas une information nouvelle.$wb$),
  ($wb$avance$wb$, $wb$D’après la mesure WestBourse sur 2008-2023, qu’ont fait en moyenne les titres les plus mal notés dans les 20 séances suivantes ?$wb$, $wb$["Ils ont continué à baisser en moyenne", "Mieux que le marché, en moyenne", "Ils ont tous été suspendus de cotation", "Exactement comme le marché"]$wb$::jsonb, 1, $wb$Sur 2008-2023, 276 cas indépendants ont fait en moyenne 8,4 % de mieux que le marché à 20 séances. Sur 2024-2026, l’effet n’est pas confirmé à 60 séances. C’est une moyenne passée, ni une règle ni une promesse.$wb$),
  ($wb$avance$wb$, $wb$Une bougie a un corps clair. Qu’est-ce que cela signifie ?$wb$, $wb$["La clôture est sous l’ouverture", "La clôture est au-dessus de l’ouverture", "Il n’y a pas eu d’échange", "Le cours a atteint un record"]$wb$::jsonb, 1, $wb$Un corps clair (ou vert) indique une clôture supérieure à l’ouverture.$wb$),
  ($wb$avance$wb$, $wb$Que représente la mèche basse ?$wb$, $wb$["La clôture", "Le plus bas atteint pendant la période", "Le dividende", "Le volume"]$wb$::jsonb, 1, $wb$La mèche basse descend jusqu’au plus bas de la période.$wb$),
  ($wb$avance$wb$, $wb$Un doji traduit plutôt :$wb$, $wb$["Une forte hausse", "Une hésitation entre acheteurs et vendeurs", "Une suspension", "Un dividende"]$wb$::jsonb, 1, $wb$Ouverture et clôture presque égales : aucun camp ne l’a emporté.$wb$),
  ($wb$avance$wb$, $wb$Une valeur n’a eu aucun échange dans la séance. À quoi ressemble sa bougie ?$wb$, $wb$["À un marteau", "À un trait plat, sans information", "À un avalement", "À une étoile filante"]$wb$::jsonb, 1, $wb$Sans transaction, les quatre prix sont identiques.$wb$),
  ($wb$avance$wb$, $wb$Comment confirmer une configuration de chandeliers ?$wb$, $wb$["Par la couleur du logo", "Par la séance suivante et par le volume", "Par le PER", "Elle n’a pas besoin de confirmation"]$wb$::jsonb, 1, $wb$Une configuration isolée est un indice ; la suite des cours et le volume la confirment ou non.$wb$),
  ($wb$avance$wb$, $wb$Quelle est la moyenne mobile sur 4 séances des clôtures 200, 210, 190 et 220 ?$wb$, $wb$["200", "205", "210", "820"]$wb$::jsonb, 1, $wb$(200 + 210 + 190 + 220) ÷ 4 = 205.$wb$),
  ($wb$avance$wb$, $wb$Le cours est au-dessus de sa moyenne sur 20 séances et de sa moyenne sur 50 séances. Comment le décrire ?$wb$, $wb$["Tendance baissière", "Tendance haussière", "Valeur suspendue", "Achat garanti"]$wb$::jsonb, 1, $wb$Un cours au-dessus de ses deux moyennes décrit une tendance haussière, sans rien garantir.$wb$),
  ($wb$avance$wb$, $wb$Pourquoi un croisement de moyennes arrive-t-il en retard ?$wb$, $wb$["Parce que les moyennes regardent les cours passés", "Parce que la BRVM publie tard", "Parce que le volume est faible", "Il n’arrive jamais en retard"]$wb$::jsonb, 0, $wb$Une moyenne se calcule sur des cours passés : elle réagit après le mouvement.$wb$),
  ($wb$avance$wb$, $wb$Dans un marché sans tendance, les croisements de moyennes :$wb$, $wb$["Sont très fiables", "Se multiplient et donnent beaucoup de faux signaux", "Disparaissent", "Annoncent un dividende"]$wb$::jsonb, 1, $wb$Quand le cours oscille, les moyennes se croisent souvent sans tendance réelle.$wb$),
  ($wb$avance$wb$, $wb$Un cours vaut 110 et sa moyenne 100. Quel est son écart à la moyenne ?$wb$, $wb$["+1 %", "+10 %", "+110 %", "−10 %"]$wb$::jsonb, 1, $wb$(110 − 100) ÷ 100 = +10 %.$wb$),
  ($wb$avance$wb$, $wb$La hausse moyenne vaut 3 et la baisse moyenne 1. Quel est le RSI ?$wb$, $wb$["25", "50", "75", "300"]$wb$::jsonb, 2, $wb$RS = 3 ; RSI = 100 − 100 ÷ (1 + 3) = 75.$wb$),
  ($wb$avance$wb$, $wb$Un RSI de 25 se situe dans quelle zone ?$wb$, $wb$["Surachat", "Neutre", "Survente", "Hors échelle"]$wb$::jsonb, 2, $wb$Sous 30, on parle de survente.$wb$),
  ($wb$avance$wb$, $wb$Un RSI reste au-dessus de 70 pendant des semaines. Est-ce possible ?$wb$, $wb$["Non, c’est impossible", "Oui, dans une forte tendance haussière", "Seulement pour les obligations", "Seulement les jours fériés"]$wb$::jsonb, 1, $wb$Une tendance forte peut maintenir le RSI en zone de surachat.$wb$),
  ($wb$avance$wb$, $wb$Pourquoi le RSI d’une valeur peu liquide est-il à lire avec prudence ?$wb$, $wb$["Il ne se calcule pas sans volume quotidien", "Quelques ordres suffisent à le pousser à l’extrême", "Il n’est publié qu’une fois par mois pour ces valeurs", "Il est interdit sur les petites valeurs"]$wb$::jsonb, 1, $wb$Avec peu d’échanges, quelques ordres font bouger le cours, et donc le RSI.$wb$),
  ($wb$avance$wb$, $wb$Que dit le RSI sur les comptes d’une société ?$wb$, $wb$["Tout", "Rien : il ne mesure que les mouvements de cours", "Son bénéfice", "Son dividende"]$wb$::jsonb, 1, $wb$Le RSI est calculé sur les cours seulement.$wb$),
  ($wb$avance$wb$, $wb$La moyenne exponentielle 12 vaut 250 et la 26 vaut 240. Que vaut la ligne MACD ?$wb$, $wb$["−10", "+10", "490", "250"]$wb$::jsonb, 1, $wb$250 − 240 = +10.$wb$),
  ($wb$avance$wb$, $wb$L’histogramme est positif et croissant. Que décrit-il ?$wb$, $wb$["Une baisse qui accélère", "Une hausse qui accélère", "Une suspension", "Un dividende"]$wb$::jsonb, 1, $wb$Positif et croissant : la tendance haussière s’accélère.$wb$),
  ($wb$avance$wb$, $wb$Pourquoi ne pas comparer le MACD de deux actions différentes ?$wb$, $wb$["Il est confidentiel", "Sa valeur dépend du niveau du cours", "Il est toujours égal", "Il est borné de 0 à 100"]$wb$::jsonb, 1, $wb$Le MACD s’exprime en points de cours : il dépend du prix de l’action.$wb$),
  ($wb$avance$wb$, $wb$Qu’est-ce qui distingue une moyenne exponentielle d’une moyenne simple ?$wb$, $wb$["Elle ignore les séances récentes", "Elle donne plus de poids aux séances récentes", "Elle ne se calcule que sur les dividendes", "Rien"]$wb$::jsonb, 1, $wb$Les séances récentes pèsent plus : la moyenne réagit plus vite.$wb$),
  ($wb$avance$wb$, $wb$Quels sont les paramètres usuels du MACD ?$wb$, $wb$["5, 10, 15", "12, 26, 9", "14, 70, 30", "20, 50, 200"]$wb$::jsonb, 1, $wb$12 et 26 pour les moyennes, 9 pour la ligne de signal.$wb$),
  ($wb$avance$wb$, $wb$Une tête-épaules suggère plutôt :$wb$, $wb$["Une continuation haussière", "Un retournement baissier", "Un dividende", "Une suspension"]$wb$::jsonb, 1, $wb$Trois sommets, celui du milieu le plus haut : figure de retournement baissier.$wb$),
  ($wb$avance$wb$, $wb$Quand une figure est-elle confirmée ?$wb$, $wb$["Dès qu’on la voit", "Quand le cours clôture au-delà du niveau clé, avec du volume", "Quand le RSI vaut 50", "Jamais"]$wb$::jsonb, 1, $wb$La cassure du niveau clé, en clôture et avec du volume, confirme la figure.$wb$),
  ($wb$avance$wb$, $wb$Un double creux se confirme par :$wb$, $wb$["La cassure du creux le plus bas", "La cassure du sommet intermédiaire", "Une baisse du volume", "Un nouveau dividende"]$wb$::jsonb, 1, $wb$Le double creux est confirmé quand le cours dépasse le sommet entre les deux creux.$wb$),
  ($wb$avance$wb$, $wb$Pourquoi une cassure sur une valeur peu liquide est-elle suspecte ?$wb$, $wb$["Elle est interdite", "Elle peut venir d’un seul ordre isolé", "Elle est toujours fiable", "Elle n’existe pas"]$wb$::jsonb, 1, $wb$Avec peu d’échanges, un ordre isolé suffit à franchir un niveau.$wb$),
  ($wb$avance$wb$, $wb$Un triangle est le plus souvent une figure de :$wb$, $wb$["Retournement", "Continuation", "Liquidation", "Dividende"]$wb$::jsonb, 1, $wb$Le triangle traduit le plus souvent une pause avant la reprise de la tendance.$wb$),
  ($wb$avance$wb$, $wb$Portefeuille de 2 000 000 FCFA, risque accepté de 2 % par position. Quel est le risque maximal ?$wb$, $wb$["4 000 FCFA", "40 000 FCFA", "400 000 FCFA", "20 000 FCFA"]$wb$::jsonb, 1, $wb$2 000 000 × 2 % = 40 000 FCFA.$wb$),
  ($wb$avance$wb$, $wb$Achat à 3 000 FCFA, stop à 2 700 FCFA, risque maximal de 30 000 FCFA. Combien d’actions acheter ?$wb$, $wb$["10", "100", "300", "1 000"]$wb$::jsonb, 1, $wb$Risque par action : 300 FCFA ; 30 000 ÷ 300 = 100 actions.$wb$),
  ($wb$avance$wb$, $wb$Stop à 900, achat à 1 000, objectif à 1 300. Quel est le rapport gain sur risque ?$wb$, $wb$["1", "2", "3", "13"]$wb$::jsonb, 2, $wb$Gain visé 300, risque 100 : rapport de 3.$wb$),
  ($wb$avance$wb$, $wb$Pourquoi un stop ne garantit-il pas le prix de vente à la BRVM ?$wb$, $wb$["Il s’exécute au cours de clôture de la veille", "Le cours peut sauter le niveau du stop", "Les stops sont toujours exécutés au cours d’achat", "La BRVM rembourse la différence au vendeur"]$wb$::jsonb, 1, $wb$Sans contrepartie au niveau du stop, la vente se fait au prix suivant disponible.$wb$),
  ($wb$avance$wb$, $wb$Quelle est l’erreur la plus coûteuse avec un stop ?$wb$, $wb$["Le fixer avant d’acheter", "Le reculer vers le bas quand le cours s’en approche", "Calculer la taille de position", "Noter son raisonnement"]$wb$::jsonb, 1, $wb$Reculer son stop transforme une perte contrôlée en perte non contrôlée.$wb$),
  ($wb$expert$wb$, $wb$Quelle institution a succédé à l’ex-CREPMF ?$wb$, $wb$["La BCEAO", "L’AMF-UMOA", "La BRVM", "La Commission bancaire"]$wb$::jsonb, 1, $wb$L’AMF-UMOA a succédé au CREPMF le 1er octobre 2022, à l’entrée en vigueur du Traité révisé de l’UMOA.$wb$),
  ($wb$expert$wb$, $wb$Qui est seul habilité à négocier vos ordres en bourse ?$wb$, $wb$["Votre banque, quelle qu’elle soit", "Une SGI agréée", "La BRVM directement", "Le Dépositaire central"]$wb$::jsonb, 1, $wb$Les ordres de bourse passent obligatoirement par une SGI agréée.$wb$),
  ($wb$expert$wb$, $wb$Quel est le rôle du Dépositaire central / Banque de règlement ?$wb$, $wb$["Fixer les cours", "Conserver les titres et régler les transactions", "Agréer les SGI", "Publier les comptes des sociétés"]$wb$::jsonb, 1, $wb$Il assure la conservation centrale des titres, le règlement et la livraison.$wb$),
  ($wb$expert$wb$, $wb$La BRVM garantit-elle la solidité des sociétés cotées ?$wb$, $wb$["Oui, elle garantit toutes les sociétés cotées", "Non : elle organise la cotation", "Oui, pour le compartiment Prestige", "Seulement pour les banques cotées"]$wb$::jsonb, 1, $wb$La cotation n’est pas une garantie : l’investisseur reste exposé au risque de la société.$wb$),
  ($wb$expert$wb$, $wb$Quel organe la réforme de 2022 a-t-elle créé au sein de l’AMF-UMOA ?$wb$, $wb$["Une banque centrale", "Une Commission des sanctions", "Une nouvelle bourse", "Un fonds de garantie des dépôts"]$wb$::jsonb, 1, $wb$La réforme a doté l’AMF-UMOA d’une Commission des sanctions et d’un Médiateur.$wb$),
  ($wb$expert$wb$, $wb$Quels sont les trois caractères d’une information privilégiée ?$wb$, $wb$["Ancienne, publique, sans effet", "Précise, non publique, susceptible d’influencer le cours", "Vague, publique, chiffrée", "Officielle, ancienne, confidentielle"]$wb$::jsonb, 1, $wb$Une information privilégiée est précise, non encore publique, et susceptible d’influencer sensiblement le cours.$wb$),
  ($wb$expert$wb$, $wb$Une société signe un contrat majeur. Que lui impose l’information permanente ?$wb$, $wb$["D’attendre la publication du rapport annuel", "De le rendre public sans délai", "De n’en parler qu’aux grands actionnaires", "Rien tant que le contrat n’est pas exécuté"]$wb$::jsonb, 1, $wb$Tout fait susceptible d’influencer sensiblement le cours doit être publié sans délai.$wb$),
  ($wb$expert$wb$, $wb$Des achats répétés en fin de séance pour gonfler le cours de clôture relèvent :$wb$, $wb$["D’une stratégie normale", "De la manipulation de cours", "D’une information périodique", "D’un dividende"]$wb$::jsonb, 1, $wb$Fixer artificiellement un cours par ses ordres est une manipulation.$wb$),
  ($wb$expert$wb$, $wb$Un ami salarié d’une société cotée vous annonce un excellent résultat, pas encore publié. Que faire ?$wb$, $wb$["Acheter avant que l’annonce ne soit publiée", "Ne pas opérer : l’information est privilégiée", "La relayer à d’autres pour qu’ils en profitent", "Vendre à découvert pour couvrir le risque"]$wb$::jsonb, 1, $wb$Utiliser ou transmettre une information privilégiée est interdit, pour lui comme pour vous.$wb$),
  ($wb$expert$wb$, $wb$Qui enquête et sanctionne les abus de marché dans l’UMOA ?$wb$, $wb$["La BRVM seule", "L’AMF-UMOA", "Chaque SGI", "Personne"]$wb$::jsonb, 1, $wb$L’AMF-UMOA enquête et sanctionne ; des poursuites pénales relèvent des législations nationales.$wb$),
  ($wb$expert$wb$, $wb$Depuis quand le marché des actions de la BRVM est-il organisé en compartiments Prestige, Principal et Croissance ?$wb$, $wb$["1998", "2 janvier 2023", "1er octobre 2022", "2026"]$wb$::jsonb, 1, $wb$La réorganisation est entrée en vigueur le 2 janvier 2023.$wb$),
  ($wb$expert$wb$, $wb$Quel flottant minimum le compartiment Prestige exige-t-il ?$wb$, $wb$["5 % du capital", "20 % du capital", "50 % du capital", "Aucun"]$wb$::jsonb, 1, $wb$Le communiqué de la BRVM fixe un flottant d’au moins 20 % du capital, assorti d’un nombre minimal de titres fixé par le règlement des compartiments.$wb$),
  ($wb$expert$wb$, $wb$Que regroupe l’indice BRVM 30 ?$wb$, $wb$["Les 30 plus grandes capitalisations", "Les 30 valeurs les plus échangées sur un trimestre", "Les 30 plus anciennes sociétés", "30 obligations"]$wb$::jsonb, 1, $wb$Le BRVM 30 regroupe les trente valeurs les plus échangées sur un trimestre.$wb$),
  ($wb$expert$wb$, $wb$À qui s’adresse le compartiment Croissance ?$wb$, $wb$["Aux banques uniquement", "Aux PME et aux entreprises à fort potentiel de croissance", "Aux États", "Aux OPCVM"]$wb$::jsonb, 1, $wb$Le compartiment Croissance est destiné aux PME et aux entreprises à fort potentiel de croissance.$wb$),
  ($wb$expert$wb$, $wb$Une société du compartiment Prestige est-elle un placement sans risque ?$wb$, $wb$["Oui, puisqu’elle est parmi les plus grandes", "Non : le compartiment ne dit rien du cours", "Oui, si elle verse un dividende régulier", "Oui, pendant ses dix premières années"]$wb$::jsonb, 1, $wb$Le classement repose sur des critères de taille, de flottant et d’information, pas sur une garantie de performance.$wb$),
  ($wb$expert$wb$, $wb$Dans une offre publique de vente, à qui va l’argent des souscripteurs ?$wb$, $wb$["À la société", "Aux actionnaires qui cèdent leurs titres", "À la BRVM", "À l’AMF-UMOA"]$wb$::jsonb, 1, $wb$Une OPV porte sur des actions existantes : le produit va aux vendeurs.$wb$),
  ($wb$expert$wb$, $wb$Une offre de 10 millions d’actions reçoit des demandes pour 14,2 millions. Quel est le taux de souscription ?$wb$, $wb$["70 %", "100 %", "142 %", "242 %"]$wb$::jsonb, 2, $wb$14,2 ÷ 10 = 142 %.$wb$),
  ($wb$expert$wb$, $wb$Dans le même cas, si toutes les demandes sont réduites de façon égale, quelle part de sa demande chacun reçoit-il ?$wb$, $wb$["Environ 50 %", "Environ 70 %", "100 %", "142 %"]$wb$::jsonb, 1, $wb$10 ÷ 14,2 ≈ 70 % de la demande servie.$wb$),
  ($wb$expert$wb$, $wb$Quelle contrainte durable accepte une société en entrant en bourse ?$wb$, $wb$["Ne plus jamais verser de dividende", "Publier régulièrement ses comptes et les faits importants", "Fermer son capital", "Changer de pays"]$wb$::jsonb, 1, $wb$La cotation impose une information périodique et permanente, sous le contrôle de l’AMF-UMOA.$wb$),
  ($wb$expert$wb$, $wb$Une introduction très sursouscrite garantit-elle une hausse du cours ?$wb$, $wb$["Oui, au moins pendant la première année", "Non : la demande ne fixe pas le cours futur", "Oui, si la société cotée est une banque solide", "Oui, dès la première séance de cotation"]$wb$::jsonb, 1, $wb$Une forte demande ne garantit rien. Le cours dépend ensuite des résultats et du prix payé.$wb$),
  ($wb$expert$wb$, $wb$Quelle étape doit précéder toute offre au public ?$wb$, $wb$["La première cotation", "Le visa de l’AMF-UMOA sur la note d’information", "Le versement d’un dividende", "L’allocation des titres"]$wb$::jsonb, 1, $wb$Aucune offre au public ne peut être ouverte avant le visa de l’AMF-UMOA.$wb$),
  ($wb$expert$wb$, $wb$Que signifie le visa de l’AMF-UMOA ?$wb$, $wb$["Que l’investissement est recommandé", "Que l’information est complète et compréhensible", "Que le cours montera", "Que la société est garantie par l’État"]$wb$::jsonb, 1, $wb$Le visa porte sur l’information, pas sur l’opportunité d’investir.$wb$),
  ($wb$expert$wb$, $wb$Qui conduit l’opération et organise le placement auprès du public ?$wb$, $wb$["La BCEAO", "La SGI chef de file", "Le Dépositaire central", "Chaque investisseur"]$wb$::jsonb, 1, $wb$La SGI chef de file pilote l’opération et centralise les ordres.$wb$),
  ($wb$expert$wb$, $wb$Vous demandez 1 000 titres dans une offre sursouscrite à 200 %, avec une réduction proportionnelle. Combien en recevez-vous ?$wb$, $wb$["250", "500", "1 000", "2 000"]$wb$::jsonb, 1, $wb$À 200 %, chaque ordre est servi à moitié : 500 titres.$wb$),
  ($wb$expert$wb$, $wb$Le cours peut-il passer sous le prix d’offre après la première cotation ?$wb$, $wb$["Non, jamais", "Oui : le prix d’offre n’est pas un plancher", "Seulement le premier jour", "Seulement pour les PME"]$wb$::jsonb, 1, $wb$Après la cotation, le cours résulte de l’offre et de la demande.$wb$);
