-- 0239 — Banque d'examen reconstruite depuis les quiz relus (2026-11-15).
--
-- La banque `academy_exam_questions` avait été amorcée (scraper/scripts/seed-exam-bank.mjs)
-- avec les QCM d'ANCIENNES versions des leçons, avant les réécritures 0228-0236 et la
-- relecture 0238 : 39 questions « quiz » périmées (dont « ordre au marché ») et 27
-- « inédites » jamais relues, dont certaines formulées comme des signaux.
-- Désormais : les 169 questions des quiz de leçon relus (0238), par niveau :
-- debutant 59, intermediaire 50, avance 35, expert 25 (un examen en tire 20).
--
-- Rien n'est supprimé : les anciennes questions passent à active = false (les tentatives
-- passées gardent leurs références). Idempotent : une question déjà active n'est pas
-- réinsérée, et la désactivation épargne les questions courantes.
-- Source : frontend/lib/academy/contenus/**/*.json (champ quiz), générée par script.

begin;

create temporary table _banque (niveau text, question text, options jsonb, correct int, explication text) on commit drop;

update public.academy_exam_questions q
   set active = false
 where q.active
   and not exists (select 1 from _banque b where b.niveau = q.niveau and b.question = q.question
                   and b.options = q.options and b.correct = q.correct and q.source = 'quiz');

select b.niveau, b.question, b.options, b.correct, b.explication, 'quiz', true
  from _banque b
 where not exists (select 1 from public.academy_exam_questions q
                    where q.active and q.niveau = b.niveau and q.question = b.question
                      and q.options = b.options and q.correct = b.correct);

commit;

